    ok(/'winter_closed', 'age', 'all'\]\.includes\(hf\)/.test(app) && /winter_closed: \(x\) => !!x\.winter_closed_order/.test(app), 'Reiter „Winterauftrag abgeschlossen, Lage offen“ (Direktsprung + Filter)');
