  for (const q of ['гальма', 'ГАЛЬМА', 'Гальма', 'скриплять', 'ölverlust', 'ÖLVERLUST', 'Ölverlust', 'links гальма', 'ölverlust  Гальма']) ok(await hit(q), 'gefunden: ' + q);
