  const mi = q.items.find((i) => i.check === 'missing_inspection' && i.plate === 'DO-VS 1'); ok(mi && Array.isArray(mi.detail_args.kinds) && mi.detail_args.kinds.includes('Tachograph'), JSON.stringify(mi));
